-- Pay MVP schema for PostgreSQL.
--
-- This migration intentionally creates only the 15 MVP tables. Authorization
-- receipts, transactional outbox events, audit events, refunds, cancellations,
-- and disputes are outside the MVP scope.
--
-- UUIDs are generated by the application and stored as CHAR(36), matching the
-- current physical ERD decision. IDs owned by other services are stored as
-- external references and do not receive cross-database foreign keys.

CREATE TABLE merchant_accounts (
    id CHAR(36) NOT NULL,
    merchant_id VARCHAR(100) NOT NULL,
    display_name VARCHAR(200) NOT NULL,
    auth_type VARCHAR(30) NOT NULL,
    credential_ref VARCHAR(255),
    status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_merchant_accounts PRIMARY KEY (id),
    CONSTRAINT uq_merchant_accounts_merchant_id UNIQUE (merchant_id)
);

CREATE TABLE payment_methods (
    id CHAR(36) NOT NULL,
    user_id CHAR(36) NOT NULL,
    provider VARCHAR(50) NOT NULL,
    provider_token_ref VARCHAR(255) NOT NULL,
    brand VARCHAR(30),
    last4 CHAR(4),
    expiry_month SMALLINT,
    expiry_year SMALLINT,
    status VARCHAR(20) NOT NULL,
    is_default BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at TIMESTAMPTZ(6),
    CONSTRAINT pk_payment_methods PRIMARY KEY (id),
    CONSTRAINT uq_payment_methods_id_user UNIQUE (id, user_id),
    CONSTRAINT chk_payment_methods_expiry_month
        CHECK (expiry_month IS NULL OR expiry_month BETWEEN 1 AND 12),
    CONSTRAINT chk_payment_methods_expiry_year
        CHECK (expiry_year IS NULL OR expiry_year >= 0)
);

CREATE INDEX idx_payment_methods_user_id
    ON payment_methods (user_id);

CREATE TABLE payment_pin_credentials (
    id CHAR(36) NOT NULL,
    user_id CHAR(36) NOT NULL,
    pin_hash VARCHAR(255) NOT NULL,
    failed_attempts INTEGER NOT NULL DEFAULT 0,
    locked_until TIMESTAMPTZ(6),
    status VARCHAR(20) NOT NULL,
    updated_at TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_payment_pin_credentials PRIMARY KEY (id),
    CONSTRAINT chk_payment_pin_credentials_failed_attempts
        CHECK (failed_attempts >= 0)
);

CREATE INDEX idx_payment_pin_credentials_user_id
    ON payment_pin_credentials (user_id);

CREATE TABLE biometric_credentials (
    id CHAR(36) NOT NULL,
    user_id CHAR(36) NOT NULL,
    device_id VARCHAR(150) NOT NULL,
    public_key TEXT NOT NULL,
    status VARCHAR(20) NOT NULL,
    registered_at TIMESTAMPTZ(6) NOT NULL,
    revoked_at TIMESTAMPTZ(6),
    CONSTRAINT pk_biometric_credentials PRIMARY KEY (id)
);

CREATE INDEX idx_biometric_credentials_user_id
    ON biometric_credentials (user_id);

CREATE TABLE authorization_sessions (
    id CHAR(36) NOT NULL,
    purchase_request_id CHAR(36) NOT NULL,
    user_id CHAR(36) NOT NULL,
    merchant_account_id CHAR(36) NOT NULL,
    external_checkout_id VARCHAR(150) NOT NULL,
    checkout_digest CHAR(64) NOT NULL,
    amount_minor BIGINT NOT NULL,
    currency CHAR(3) NOT NULL,
    selected_payment_method_id CHAR(36),
    status VARCHAR(30) NOT NULL,
    idempotency_key VARCHAR(100) NOT NULL,
    request_hash CHAR(64) NOT NULL,
    required_action VARCHAR(20) NOT NULL DEFAULT 'BIOMETRIC',
    expires_at TIMESTAMPTZ(6) NOT NULL,
    approved_at TIMESTAMPTZ(6),
    auth_method VARCHAR(20),
    created_at TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    version INTEGER NOT NULL DEFAULT 0,
    active_purchase_request_key CHAR(36)
        GENERATED ALWAYS AS (
            CASE
                WHEN status IN ('PAYMENT_METHOD_REQUIRED', 'PENDING', 'APPROVED')
                    THEN purchase_request_id
                ELSE NULL
            END
        ) STORED,
    CONSTRAINT pk_authorization_sessions PRIMARY KEY (id),
    CONSTRAINT uq_authorization_sessions_idempotency
        UNIQUE (merchant_account_id, idempotency_key),
    CONSTRAINT uq_authorization_sessions_active_purchase_request
        UNIQUE (merchant_account_id, active_purchase_request_key),
    CONSTRAINT chk_authorization_sessions_amount
        CHECK (amount_minor >= 0),
    CONSTRAINT chk_authorization_sessions_status
        CHECK (status IN (
            'PAYMENT_METHOD_REQUIRED',
            'PENDING',
            'APPROVED',
            'REJECTED',
            'EXPIRED',
            'INVALIDATED'
        )),
    CONSTRAINT chk_authorization_sessions_required_action
        CHECK (required_action IN ('BIOMETRIC', 'PIN')),
    CONSTRAINT chk_authorization_sessions_auth_method
        CHECK (auth_method IS NULL OR auth_method IN ('BIOMETRIC', 'PIN')),
    CONSTRAINT chk_authorization_sessions_payment_method_state
        CHECK (
            (status = 'PAYMENT_METHOD_REQUIRED' AND selected_payment_method_id IS NULL)
            OR (status <> 'PAYMENT_METHOD_REQUIRED' AND selected_payment_method_id IS NOT NULL)
        ),
    CONSTRAINT fk_authorization_sessions_merchant
        FOREIGN KEY (merchant_account_id)
        REFERENCES merchant_accounts (id)
        ON DELETE RESTRICT,
    CONSTRAINT fk_authorization_sessions_payment_method
        FOREIGN KEY (selected_payment_method_id, user_id)
        REFERENCES payment_methods (id, user_id)
        ON DELETE RESTRICT
);

CREATE INDEX idx_authorization_sessions_purchase_request
    ON authorization_sessions (purchase_request_id);

CREATE INDEX idx_authorization_sessions_merchant_account_id
    ON authorization_sessions (merchant_account_id);

CREATE INDEX idx_authorization_sessions_payment_method_id
    ON authorization_sessions (selected_payment_method_id);

CREATE TABLE biometric_challenges (
    id CHAR(36) NOT NULL,
    biometric_credential_id CHAR(36) NOT NULL,
    authorization_session_id CHAR(36) NOT NULL,
    challenge_hash CHAR(64) NOT NULL,
    status VARCHAR(20) NOT NULL,
    expires_at TIMESTAMPTZ(6) NOT NULL,
    used_at TIMESTAMPTZ(6),
    created_at TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_biometric_challenges PRIMARY KEY (id),
    CONSTRAINT uq_biometric_challenges_hash UNIQUE (challenge_hash),
    CONSTRAINT chk_biometric_challenges_status
        CHECK (status IN ('PENDING', 'SUCCESS', 'FAILED', 'EXPIRED')),
    CONSTRAINT fk_biometric_challenges_credential
        FOREIGN KEY (biometric_credential_id)
        REFERENCES biometric_credentials (id)
        ON DELETE RESTRICT,
    CONSTRAINT fk_biometric_challenges_session
        FOREIGN KEY (authorization_session_id)
        REFERENCES authorization_sessions (id)
        ON DELETE RESTRICT
);

CREATE INDEX idx_biometric_challenges_credential_id
    ON biometric_challenges (biometric_credential_id);

CREATE INDEX idx_biometric_challenges_session_id
    ON biometric_challenges (authorization_session_id);

CREATE TABLE pay_verified_checkout_evidence (
    id CHAR(36) NOT NULL,
    authorization_session_id CHAR(36) NOT NULL,
    merchant_id VARCHAR(100) NOT NULL,
    external_checkout_id VARCHAR(150) NOT NULL,
    checkout_digest CHAR(64) NOT NULL,
    canonical_checkout_json JSONB NOT NULL,
    merchant_authorization TEXT NOT NULL,
    signature_algorithm VARCHAR(30) NOT NULL,
    signature_verified BOOLEAN NOT NULL DEFAULT FALSE,
    amount_minor BIGINT NOT NULL,
    currency CHAR(3) NOT NULL,
    verified_at TIMESTAMPTZ(6) NOT NULL,
    expires_at TIMESTAMPTZ(6) NOT NULL,
    CONSTRAINT pk_pay_verified_checkout_evidence PRIMARY KEY (id),
    CONSTRAINT uq_checkout_evidence_identity
        UNIQUE (merchant_id, external_checkout_id, checkout_digest),
    CONSTRAINT uq_checkout_evidence_session UNIQUE (authorization_session_id),
    CONSTRAINT chk_checkout_evidence_amount CHECK (amount_minor >= 0),
    CONSTRAINT fk_checkout_evidence_session
        FOREIGN KEY (authorization_session_id)
        REFERENCES authorization_sessions (id)
        ON DELETE RESTRICT
);

CREATE INDEX idx_checkout_evidence_checkout
    ON pay_verified_checkout_evidence (merchant_id, external_checkout_id);

CREATE TABLE checkout_mandates (
    id CHAR(36) NOT NULL,
    authorization_session_id CHAR(36) NOT NULL,
    jti VARCHAR(100) NOT NULL,
    issuer VARCHAR(200) NOT NULL,
    audience VARCHAR(200) NOT NULL,
    checkout_digest CHAR(64) NOT NULL,
    signed_artifact_encrypted TEXT NOT NULL,
    artifact_hash CHAR(64) NOT NULL,
    status VARCHAR(20) NOT NULL,
    issued_at TIMESTAMPTZ(6) NOT NULL,
    expires_at TIMESTAMPTZ(6) NOT NULL,
    CONSTRAINT pk_checkout_mandates PRIMARY KEY (id),
    CONSTRAINT uq_checkout_mandates_jti UNIQUE (jti),
    CONSTRAINT uq_checkout_mandates_session UNIQUE (authorization_session_id),
    CONSTRAINT chk_checkout_mandates_status
        CHECK (status IN ('ISSUED', 'EXPIRED', 'REVOKED')),
    CONSTRAINT fk_checkout_mandates_session
        FOREIGN KEY (authorization_session_id)
        REFERENCES authorization_sessions (id)
        ON DELETE RESTRICT
);

CREATE INDEX idx_checkout_mandates_digest
    ON checkout_mandates (checkout_digest);

CREATE TABLE payment_mandates (
    id CHAR(36) NOT NULL,
    authorization_session_id CHAR(36) NOT NULL,
    jti VARCHAR(100) NOT NULL,
    transaction_id VARCHAR(100) NOT NULL,
    merchant_id VARCHAR(100) NOT NULL,
    external_checkout_id VARCHAR(150) NOT NULL,
    amount_minor BIGINT NOT NULL,
    currency CHAR(3) NOT NULL,
    payment_method_ref VARCHAR(255) NOT NULL,
    signed_artifact_encrypted TEXT NOT NULL,
    artifact_hash CHAR(64) NOT NULL,
    status VARCHAR(20) NOT NULL,
    issued_at TIMESTAMPTZ(6) NOT NULL,
    expires_at TIMESTAMPTZ(6) NOT NULL,
    CONSTRAINT pk_payment_mandates PRIMARY KEY (id),
    CONSTRAINT uq_payment_mandates_jti UNIQUE (jti),
    CONSTRAINT uq_payment_mandates_transaction_id UNIQUE (transaction_id),
    CONSTRAINT uq_payment_mandates_session UNIQUE (authorization_session_id),
    CONSTRAINT chk_payment_mandates_amount CHECK (amount_minor >= 0),
    CONSTRAINT chk_payment_mandates_status
        CHECK (status IN ('ISSUED', 'EXPIRED', 'REVOKED')),
    CONSTRAINT fk_payment_mandates_session
        FOREIGN KEY (authorization_session_id)
        REFERENCES authorization_sessions (id)
        ON DELETE RESTRICT
);

CREATE INDEX idx_payment_mandates_checkout
    ON payment_mandates (merchant_id, external_checkout_id);

CREATE TABLE payment_credential_tokens (
    id CHAR(36) NOT NULL,
    authorization_session_id CHAR(36) NOT NULL,
    checkout_mandate_id CHAR(36) NOT NULL,
    payment_mandate_id CHAR(36) NOT NULL,
    token_hash CHAR(64) NOT NULL,
    token_ciphertext TEXT NOT NULL,
    merchant_id VARCHAR(100) NOT NULL,
    external_checkout_id VARCHAR(150) NOT NULL,
    checkout_digest CHAR(64) NOT NULL,
    amount_minor BIGINT NOT NULL,
    currency CHAR(3) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'ISSUED',
    issued_at TIMESTAMPTZ(6) NOT NULL,
    expires_at TIMESTAMPTZ(6) NOT NULL,
    consumed_at TIMESTAMPTZ(6),
    CONSTRAINT pk_payment_credential_tokens PRIMARY KEY (id),
    CONSTRAINT uq_payment_credentials_token_hash UNIQUE (token_hash),
    CONSTRAINT uq_payment_credentials_session UNIQUE (authorization_session_id),
    CONSTRAINT uq_payment_credentials_checkout_mandate UNIQUE (checkout_mandate_id),
    CONSTRAINT uq_payment_credentials_payment_mandate UNIQUE (payment_mandate_id),
    CONSTRAINT chk_payment_credentials_amount CHECK (amount_minor >= 0),
    CONSTRAINT chk_payment_credentials_status
        CHECK (status IN ('ISSUED', 'CONSUMED', 'EXPIRED', 'REVOKED')),
    CONSTRAINT fk_payment_credentials_session
        FOREIGN KEY (authorization_session_id)
        REFERENCES authorization_sessions (id)
        ON DELETE RESTRICT,
    CONSTRAINT fk_payment_credentials_checkout_mandate
        FOREIGN KEY (checkout_mandate_id)
        REFERENCES checkout_mandates (id)
        ON DELETE RESTRICT,
    CONSTRAINT fk_payment_credentials_payment_mandate
        FOREIGN KEY (payment_mandate_id)
        REFERENCES payment_mandates (id)
        ON DELETE RESTRICT
);

CREATE INDEX idx_payment_credentials_status
    ON payment_credential_tokens (status, expires_at);

CREATE TABLE payments (
    id CHAR(36) NOT NULL,
    merchant_account_id CHAR(36) NOT NULL,
    external_checkout_id VARCHAR(150) NOT NULL,
    purchase_request_id CHAR(36) NOT NULL,
    credential_token_id CHAR(36) NOT NULL,
    amount_minor BIGINT NOT NULL,
    currency CHAR(3) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'READY',
    idempotency_key VARCHAR(100) NOT NULL,
    request_hash CHAR(64) NOT NULL,
    created_at TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    version INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT pk_payments PRIMARY KEY (id),
    CONSTRAINT uq_payments_credential_token UNIQUE (credential_token_id),
    CONSTRAINT uq_payments_merchant_idempotency
        UNIQUE (merchant_account_id, idempotency_key),
    CONSTRAINT chk_payments_amount CHECK (amount_minor >= 0),
    CONSTRAINT chk_payments_status
        CHECK (status IN ('READY', 'PROCESSING', 'SUCCESS', 'FAILED', 'UNKNOWN')),
    CONSTRAINT fk_payments_merchant
        FOREIGN KEY (merchant_account_id)
        REFERENCES merchant_accounts (id)
        ON DELETE RESTRICT,
    CONSTRAINT fk_payments_credential_token
        FOREIGN KEY (credential_token_id)
        REFERENCES payment_credential_tokens (id)
        ON DELETE RESTRICT
);

CREATE INDEX idx_payments_status
    ON payments (status);

CREATE INDEX idx_payments_purchase_request
    ON payments (purchase_request_id);

CREATE TABLE payment_attempts (
    id CHAR(36) NOT NULL,
    payment_id CHAR(36) NOT NULL,
    attempt_no INTEGER NOT NULL,
    operation VARCHAR(30) NOT NULL,
    request_hash CHAR(64) NOT NULL,
    pg_request_id VARCHAR(150),
    status VARCHAR(20) NOT NULL,
    error_code VARCHAR(100),
    started_at TIMESTAMPTZ(6) NOT NULL,
    completed_at TIMESTAMPTZ(6),
    CONSTRAINT pk_payment_attempts PRIMARY KEY (id),
    CONSTRAINT uq_payment_attempts_number UNIQUE (payment_id, attempt_no),
    CONSTRAINT uq_payment_attempts_operation UNIQUE (payment_id, operation),
    CONSTRAINT uq_payment_attempts_pg_request_id UNIQUE (pg_request_id),
    CONSTRAINT chk_payment_attempts_number CHECK (attempt_no > 0),
    CONSTRAINT chk_payment_attempts_operation CHECK (operation IN ('CHARGE')),
    CONSTRAINT chk_payment_attempts_status
        CHECK (status IN ('PROCESSING', 'SUCCESS', 'FAILED', 'UNKNOWN')),
    CONSTRAINT fk_payment_attempts_payment
        FOREIGN KEY (payment_id)
        REFERENCES payments (id)
        ON DELETE RESTRICT
);

CREATE INDEX idx_payment_attempts_payment_id
    ON payment_attempts (payment_id);

CREATE TABLE pg_transactions (
    id CHAR(36) NOT NULL,
    payment_attempt_id CHAR(36) NOT NULL,
    pg_transaction_id VARCHAR(150),
    status VARCHAR(20) NOT NULL,
    response_code VARCHAR(100),
    requested_at TIMESTAMPTZ(6) NOT NULL,
    completed_at TIMESTAMPTZ(6),
    last_checked_at TIMESTAMPTZ(6),
    CONSTRAINT pk_pg_transactions PRIMARY KEY (id),
    CONSTRAINT uq_pg_transactions_external_id UNIQUE (pg_transaction_id),
    CONSTRAINT uq_pg_transactions_attempt_id UNIQUE (payment_attempt_id),
    CONSTRAINT chk_pg_transactions_status
        CHECK (status IN ('PROCESSING', 'SUCCESS', 'FAILED', 'UNKNOWN')),
    CONSTRAINT fk_pg_transactions_attempt
        FOREIGN KEY (payment_attempt_id)
        REFERENCES payment_attempts (id)
        ON DELETE RESTRICT
);

CREATE INDEX idx_pg_transactions_status
    ON pg_transactions (status);

CREATE TABLE payment_receipts (
    id CHAR(36) NOT NULL,
    payment_id CHAR(36) NOT NULL,
    receipt_hash CHAR(64) NOT NULL,
    status VARCHAR(20) NOT NULL,
    artifact_encrypted TEXT NOT NULL,
    issued_at TIMESTAMPTZ(6) NOT NULL,
    CONSTRAINT pk_payment_receipts PRIMARY KEY (id),
    CONSTRAINT uq_payment_receipts_payment_id UNIQUE (payment_id),
    CONSTRAINT uq_payment_receipts_hash UNIQUE (receipt_hash),
    CONSTRAINT chk_payment_receipts_status CHECK (status IN ('ISSUED')),
    CONSTRAINT fk_payment_receipts_payment
        FOREIGN KEY (payment_id)
        REFERENCES payments (id)
        ON DELETE RESTRICT
);

CREATE TABLE payment_reconciliation_jobs (
    id CHAR(36) NOT NULL,
    payment_attempt_id CHAR(36) NOT NULL,
    reason VARCHAR(100) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    next_run_at TIMESTAMPTZ(6) NOT NULL,
    attempt_count INTEGER NOT NULL DEFAULT 0,
    last_run_at TIMESTAMPTZ(6),
    last_error TEXT,
    CONSTRAINT pk_payment_reconciliation_jobs PRIMARY KEY (id),
    CONSTRAINT uq_reconciliation_jobs_attempt_reason
        UNIQUE (payment_attempt_id, reason),
    CONSTRAINT chk_reconciliation_jobs_attempt_count
        CHECK (attempt_count >= 0),
    CONSTRAINT chk_reconciliation_jobs_status
        CHECK (status IN ('PENDING', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED')),
    CONSTRAINT fk_reconciliation_jobs_attempt
        FOREIGN KEY (payment_attempt_id)
        REFERENCES payment_attempts (id)
        ON DELETE RESTRICT
);

CREATE INDEX idx_reconciliation_jobs_schedule
    ON payment_reconciliation_jobs (status, next_run_at);

CREATE INDEX idx_reconciliation_jobs_attempt_id
    ON payment_reconciliation_jobs (payment_attempt_id);

-- PostgreSQL has no MySQL-style ON UPDATE clause. These triggers preserve the
-- documented updated_at behavior for the tables that expose that column.
CREATE OR REPLACE FUNCTION pay_set_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_merchant_accounts_updated_at
BEFORE UPDATE ON merchant_accounts
FOR EACH ROW
EXECUTE FUNCTION pay_set_updated_at();
CREATE TRIGGER trg_payment_pin_credentials_updated_at
BEFORE UPDATE ON payment_pin_credentials
FOR EACH ROW
EXECUTE FUNCTION pay_set_updated_at();

CREATE TRIGGER trg_authorization_sessions_updated_at
BEFORE UPDATE ON authorization_sessions
FOR EACH ROW
EXECUTE FUNCTION pay_set_updated_at();

CREATE TRIGGER trg_payments_updated_at
BEFORE UPDATE ON payments
FOR EACH ROW
EXECUTE FUNCTION pay_set_updated_at();
